package totah.lab.prometheus.variational;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;
import totah.lab.prometheus.molecular.*;
import totah.lab.prometheus.neural.GeneralSlaterJastrowState;

final class GeneralMolecularSamplingDiagnosticsTest {
    @Test void boundedLargerGeneralFixtureReportsScaleReadinessAndExactReplay(){Molecule molecule=new Molecule("synthetic-scale-fixture",List.of(new NuclearCenter(0,"X",new NuclearCharge(2),new CartesianPosition(0,0,0,LengthUnit.BOHR)),new NuclearCenter(1,"H",new NuclearCharge(1),new CartesianPosition(1.6,0,0,LengthUnit.BOHR)),new NuclearCenter(2,"H",new NuclearCharge(1),new CartesianPosition(-.5,1.4,.2,LengthUnit.BOHR))),new MolecularCharge(0),new ElectronCount(4),new SpinSector(2,2,1));var state=GeneralSlaterJastrowState.cuspInitialized(molecule);var hamiltonian=new GeneralMolecularCoulombHamiltonian(molecule);var first=new GeneralMolecularSamplingDiagnostics().evaluate(state,hamiltonian,new GeneralMolecularImportanceBatches(molecule,96,2.0,211,24));var second=new GeneralMolecularSamplingDiagnostics().evaluate(state,hamiltonian,new GeneralMolecularImportanceBatches(molecule,96,2.0,211,24));assertEquals("DETERMINISTIC_HALTON_IMPORTANCE",first.samplingMode());assertTrue(first.acceptanceRate().isEmpty());assertEquals("NOT_APPLICABLE_NO_MARKOV_PROPOSALS",first.acceptanceStatus());assertEquals(96,first.samples());assertEquals(96,first.finiteSamples());assertEquals(6.756061879824082,first.rawWeightMinimum());assertEquals(18000391.190366592,first.rawWeightMaximum());assertEquals(1.8378228743058677e-7,first.effectiveWeightMinimum());assertEquals(2039.449275953398,first.effectiveWeightMaximum());assertEquals(.3838969091160356,first.maximumNormalizedWeight());assertEquals(5.750989961152584,first.effectiveSampleSize());assertEquals(.05990614542867275,first.effectiveSampleFraction());assertEquals(-2.3935897491695193,first.localEnergyMean());assertEquals(5.207966885389234,first.localEnergyVariance());assertEquals(-1611.4232223543977,first.localEnergyMinimum());assertEquals(-6.337254250705825,first.localEnergyQ01());assertEquals(-2.8395507441328567,first.localEnergyMedian());assertEquals(3.4927985296720574,first.localEnergyQ99());assertEquals(83.91204652572364,first.localEnergyMaximum());assertEquals(.1648808399638581,first.topOnePercentVarianceFraction());assertEquals(.5602835821436957,first.topFivePercentVarianceFraction());assertEquals(-.0547009643371909,first.lagOneOrderingCorrelation());assertEquals(-.03840913401229733,first.lagTwoOrderingCorrelation());assertEquals("2d8e03712971d383eefbb2c4f053e53522472782c5bc45893b52ad9d82815dd6",first.deterministicReplayHash());assertEquals(first,second);}
}
